<?php
require "db.php";
$message="";$flight_id=(int)($_GET['flight_id']??$_POST['flight_id']??0);$airport_id=(int)($_GET['airport_id']??$_POST['airport_id']??0);
$passengers=$conn->query("SELECT passenger_id,name,email FROM passengers ORDER BY name");
$flights=$conn->query("SELECT * FROM flights WHERE seats_available>0 ORDER BY departure_date");
$airports=$conn->query("SELECT * FROM airports ORDER BY country,city,airport_name");
$selected_flight=null;if($flight_id){$s=$conn->prepare("SELECT * FROM flights WHERE flight_id=? AND seats_available>0");$s->bind_param('i',$flight_id);$s->execute();$selected_flight=$s->get_result()->fetch_assoc();}
if($_SERVER['REQUEST_METHOD']==='POST'){
  $pid=(int)$_POST['passenger_id'];$fid=(int)$_POST['flight_id'];$aid=(int)$_POST['airport_id'];$date=$_POST['booking_date'];$seat=$_POST['seat_number'];$class=$_POST['travel_class'];$count=max(1,(int)$_POST['passenger_count']);$age=$_POST['age_group'];$gender=$_POST['gender'];
  $check=$conn->prepare("SELECT booking_id FROM bookings WHERE flight_id=? AND seat_number=? AND status='Booked'");$check->bind_param('is',$fid,$seat);$check->execute();
  if($check->get_result()->num_rows){$message='<div class="notice error">That seat was just booked. Please choose another seat.</div>';} else {
    $s=$conn->prepare("INSERT INTO bookings(passenger_id,flight_id,airport_id,booking_date,seat_number,travel_class,passenger_count,age_group,gender,status) VALUES(?,?,?,?,?,?,?,?,?,'Booked')");$s->bind_param('iiisssiss',$pid,$fid,$aid,$date,$seat,$class,$count,$age,$gender);
    if($s->execute()){ $conn->query("UPDATE flights SET seats_available=GREATEST(seats_available-1,0) WHERE flight_id=".$fid); header('Location: payment.php?booking_id='.$s->insert_id); exit; }
    $message='<div class="notice error">Booking failed. Please try again.</div>';
  }
}
$booked=[];if($flight_id){$s=$conn->prepare("SELECT seat_number FROM bookings WHERE flight_id=? AND status='Booked'");$s->bind_param('i',$flight_id);$s->execute();$res=$s->get_result();while($r=$res->fetch_assoc())$booked[]=$r['seat_number'];}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Booking</title><link rel="stylesheet" href="style.css"></head><body><?php require "header.php"; ?><main class="container"><div class="page-head"><div class="eyebrow">Booking</div><h1>Complete Your Booking</h1><p>Select the registered passenger, flight, airport and seat. The flight page intentionally has no seat selector; seat selection happens here before payment.</p></div><?= $message ?>
<div class="panel"><form method="post"><input type="hidden" name="flight_id" value="<?=$flight_id?>"><div class="grid grid-2"><div class="field"><label>Registered Passenger</label><select name="passenger_id" required><option value="">Select passenger</option><?php while($r=$passengers->fetch_assoc()): ?><option value="<?=$r['passenger_id']?>">PA-<?=$r['passenger_id']?> — <?=e($r['name'])?> — <?=e($r['email'])?></option><?php endwhile;?></select></div><div class="field"><label>Flight</label><select name="flight_id" onchange="location='booking.php?flight_id='+this.value" required><option value="">Select flight</option><?php while($r=$flights->fetch_assoc()): ?><option value="<?=$r['flight_id']?>" <?=$flight_id==$r['flight_id']?'selected':''?>>FL-<?=str_pad($r['flight_id'],5,'0',STR_PAD_LEFT)?> — <?=e($r['flight_name'])?> — <?=e($r['route'])?></option><?php endwhile;?></select></div><div class="field"><label>Airport</label><select name="airport_id" required><option value="">Select airport</option><?php while($r=$airports->fetch_assoc()): ?><option value="<?=$r['airport_id']?>" <?=$airport_id==$r['airport_id']?'selected':''?>>AP-<?=str_pad($r['airport_id'],5,'0',STR_PAD_LEFT)?> — <?=e($r['airport_name'])?>, <?=e($r['city'])?></option><?php endwhile;?></select></div><div class="field"><label>Booking Date</label><input type="date" name="booking_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Travel Class</label><select name="travel_class"><option>Economy</option><option>Business</option><option>First</option></select></div><div class="field"><label>Passenger Count</label><input type="number" name="passenger_count" value="1" min="1" max="9"></div><div class="field"><label>Age Group</label><select name="age_group"><option>Adult</option><option>Child</option><option>Senior</option></select></div><div class="field"><label>Gender</label><select name="gender"><option>Male</option><option>Female</option><option>Other</option></select></div></div>
<?php if($selected_flight): ?><div class="booking-summary"><div><small>Selected flight</small><strong><?=e($selected_flight['flight_name'])?> · <?=e($selected_flight['route'])?></strong></div><div><small>Travel time</small><strong><?=e($selected_flight['travel_time']?:'—')?></strong></div><div><small>Available seats</small><strong><?=e($selected_flight['seats_available'])?></strong></div></div><div class="field"><label>Select Seat</label><div class="seat-grid"><?php for($i=1;$i<=24;$i++): $seat='A'.$i; $isbooked=in_array($seat,$booked,true); ?><label class="seat <?=$isbooked?'booked':''?>"><input type="radio" name="seat_number" value="<?=$seat?>" <?=$isbooked?'disabled':''?> required><?=$seat?><?=$isbooked?' · Booked':''?></label><?php endfor;?></div></div><p class="muted">No seat hold is used. Once you confirm the booking, the seat becomes booked and you continue directly to payment.</p><button class="btn btn-primary" type="submit">Continue to Payment</button><?php else: ?><div class="notice info">Select a flight to load the available seat map.</div><?php endif; ?> <a class="btn btn-dark" href="flights.php">Back to Flights</a></form></div></main><?php require "footer.php"; ?></body></html>
